{
  "name": "bluefront-echoes",
  "version": "1.0.0",
  "private": true,
  "description": "Co-op boss arena with lives, revive, and escalating arsenal",
  "scripts": { "start": "node server.js" },
  "dependencies": { "ws": "^8.18.0" }
}

const http = require('node:http');
const fs = require('node:fs');
const path = require('node:path');
const { WebSocketServer } = require('ws');

const PORT = Number(process.env.PORT || 3000);
const root = __dirname;
const server = http.createServer((req, res) => {
  const pathname = new URL(req.url, `http://${req.headers.host}`).pathname;
  const file = pathname === '/' ? 'index.html' : pathname.replace(/^\/+/, '');
  const target = path.resolve(root, file);
  if (!target.startsWith(root + path.sep) && target !== path.join(root, 'index.html')) {
    res.writeHead(403).end('Forbidden'); return;
  }
  fs.readFile(target, (err, data) => {
    if (err) { res.writeHead(404).end('Not found'); return; }
    const ext = path.extname(target);
    const types = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript', '.css': 'text/css', '.json': 'application/json' };
    res.writeHead(200, { 'Content-Type': types[ext] || 'application/octet-stream', 'Cache-Control': 'no-store' });
    res.end(data);
  });
});
const wss = new WebSocketServer({ noServer: true });
const players = new Map();
const catalog = {
  'field-rifle': { name: 'Field Rifle', price: 0, tier: 1, type: 'military' },
  'storm-smg': { name: 'Storm SMG', price: 80, tier: 2, type: 'military' },
  'titan-shotgun': { name: 'Titan Shotgun', price: 180, tier: 3, type: 'military' },
  'ember-staff': { name: 'Ember Staff', price: 110, tier: 2, type: 'mystic' },
  'rift-blade': { name: 'Rift Blade', price: 240, tier: 3, type: 'mystic' },
  'nova-caster': { name: 'Nova Caster', price: 420, tier: 4, type: 'mystic' }
};
function broadcast() {
  const snapshot = JSON.stringify({ type: 'snapshot', players: [...players.values()].map(({ ws, ...p }) => p) });
  for (const p of players.values()) if (p.ws.readyState === 1) p.ws.send(snapshot);
}
function send(ws, type, data = {}) { if (ws.readyState === 1) ws.send(JSON.stringify({ type, ...data })); }
function distance(a, b) { return Math.hypot(a.x - b.x, a.z - b.z); }
server.on('upgrade', (req, socket, head) => {
  if (new URL(req.url, `http://${req.headers.host}`).pathname !== '/ws') { socket.destroy(); return; }
  wss.handleUpgrade(req, socket, head, ws => wss.emit('connection', ws, req));
});
wss.on('connection', ws => {
  const id = Math.random().toString(36).slice(2, 9);
  const player = { id, name: `Ranger-${id.slice(0, 3)}`, x: (Math.random() - .5) * 7, z: (Math.random() - .5) * 7, hp: 100, lives: 3, coins: 0, state: 'alive', inventory: ['field-rifle'], revive: null, ws };
  players.set(id, player);
  send(ws, 'welcome', { id, player: { ...player, ws: undefined }, catalog }); broadcast();
  ws.on('message', raw => {
    let msg; try { msg = JSON.parse(raw); } catch { return; }
    if (msg.type === 'move' && player.state === 'alive') {
      const x = Number(msg.x), z = Number(msg.z);
      if (Number.isFinite(x) && Number.isFinite(z) && Math.hypot(x, z) < 70) { player.x = x; player.z = z; }
    }
    if (msg.type === 'damage' && player.state === 'alive') {
      const amount = Math.max(0, Math.min(35, Number(msg.amount) || 0));
      player.hp = Math.max(0, player.hp - amount);
      if (player.hp === 0) { player.lives--; player.state = player.lives > 0 ? 'alive' : 'down'; player.hp = player.lives > 0 ? 100 : 0; player.revive = null; }
      broadcast();
    }
    if (msg.type === 'revive-start') {
      const target = players.get(String(msg.target));
      if (target && target.state === 'down' && distance(player, target) < 3.2 && player.state === 'alive') {
        target.revive = { by: player.id, slaps: 0 }; send(ws, 'action', { action: 'grabbed', target: target.id }); broadcast();
      }
    }
    if (msg.type === 'revive-slap') {
      const target = players.get(String(msg.target));
      if (target && target.state === 'down' && target.revive?.by === player.id && player.state === 'alive' && distance(player, target) < 3.2) {
        target.revive.slaps++;
        if (target.revive.slaps >= 3) { target.state = 'alive'; target.lives = 1; target.hp = 60; target.revive = null; }
        send(ws, 'action', { action: 'slap', target: target.id, count: target.revive?.slaps ?? 3 }); broadcast();
      }
    }
    if (msg.type === 'buy') {
      const item = catalog[String(msg.item)];
      if (!item || player.state !== 'alive') return;
      if (player.inventory.includes(msg.item)) { send(ws, 'error', { message: 'Você já possui este equipamento.' }); return; }
      if (player.coins < item.price) { send(ws, 'error', { message: 'Moedas azuis insuficientes.' }); return; }
      player.coins -= item.price; player.inventory.push(msg.item); send(ws, 'purchased', { item: msg.item, coins: player.coins }); broadcast();
    }
    if (msg.type === 'reward') {
      const amount = Math.max(0, Math.min(30, Number(msg.amount) || 0)); player.coins += amount; broadcast();
    }
    if (msg.type === 'heartbeat') send(ws, 'pong');
  });
  ws.on('close', () => { players.delete(id); broadcast(); });
});
setInterval(broadcast, 100);
server.listen(PORT, '0.0.0.0', () => console.log(`Bluefront Echoes running at http://localhost:${PORT}`));

(() => {
  const $ = id => document.getElementById(id);
  const catalog = [
    { id:'field-rifle', name:'Field Rifle', type:'military', tier:1, price:0, glyph:'╱', desc:'Rifle de assalto • rajada precisa', damage:28 },
    { id:'storm-smg', name:'Storm SMG', type:'military', tier:2, price:80, glyph:'⌁', desc:'Submetralhadora • disparo rápido', damage:19 },
    { id:'titan-shotgun', name:'Titan Shotgun', type:'military', tier:3, price:180, glyph:'▰', desc:'Escopeta tática • alto impacto', damage:62 },
    { id:'ember-staff', name:'Ember Staff', type:'mystic', tier:2, price:110, glyph:'ϟ', desc:'Cajado ígneo • dano em área', damage:38 },
    { id:'rift-blade', name:'Rift Blade', type:'mystic', tier:3, price:240, glyph:'⚔', desc:'Lâmina elemental • corte dimensional', damage:54 },
    { id:'nova-caster', name:'Nova Caster', type:'mystic', tier:4, price:420, glyph:'✦', desc:'Pistola arcana • energia devastadora', damage:78 }
  ];
  let scene, camera, renderer, clock, player, boss, bossHp=100, hp=100, lives=3, coins=120;
  let alive=false, down=false, running=false, muted=false, shotAt=0, skillAt=0, dashAt=0, attackAt=0, nextWave=0, wave=1, phase=1;
  let inventory=['field-rifle'], weapon=catalog[0], remotes=new Map(), allies=[], enemies=[], bullets=[], pickups=[], effects=[];
  let ws=null, myId=null, lastMove=0, reviveTarget=null, reviveSlaps=0, held={}, mouse={x:innerWidth/2,y:innerHeight/2,down:false}, raycaster, groundPlane, arenaGroup;
  const playerMat=new THREE.MeshStandardMaterial({color:0x9deaf2,metalness:.65,roughness:.28,emissive:0x143f4b});
  const colors={cyan:0x63eaff,orange:0xff765d,purple:0xb18bff,green:0x5de1b0};
  function init(){
    scene=new THREE.Scene();scene.background=new THREE.Color(0x081521);scene.fog=new THREE.Fog(0x081521,25,66);
    camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,120);
    renderer=new THREE.WebGLRenderer({antialias:true,alpha:false});renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.12;$('game').appendChild(renderer.domElement);
    clock=new THREE.Clock();raycaster=new THREE.Raycaster();groundPlane=new THREE.Plane(new THREE.Vector3(0,1,0),0);
    scene.add(new THREE.HemisphereLight(0x9acfff,0x10131e,1.25));const key=new THREE.DirectionalLight(0x9beaff,2.1);key.position.set(-8,16,7);key.castShadow=true;key.shadow.mapSize.set(1024,1024);scene.add(key);
    arenaGroup=new THREE.Group();scene.add(arenaGroup);buildArena();player=makeRanger(0,0,true);scene.add(player);boss=makeBoss();scene.add(boss);spawnAllies();
    for(let i=0;i<8;i++)spawnEnemy();for(let i=0;i<5;i++)spawnCoin();
    window.addEventListener('resize',resize);window.addEventListener('keydown',keyDown);window.addEventListener('keyup',e=>held[e.code]=false);renderer.domElement.addEventListener('mousemove',e=>{mouse.x=e.clientX;mouse.y=e.clientY});renderer.domElement.addEventListener('mousedown',()=>{mouse.down=true;alive=true;$('crosshair-hint').classList.remove('show')});window.addEventListener('mouseup',()=>mouse.down=false);renderer.domElement.addEventListener('contextmenu',e=>e.preventDefault());
    $('deploy-btn').onclick=()=>{$('intro-overlay').classList.remove('open');running=true;alive=true;toast('OPERAÇÃO INICIADA // WARDEN DETECTADO')};$('shop-open').onclick=openShop;$('shop-close').onclick=closeShop;document.querySelectorAll('.shop-categories button').forEach(b=>b.onclick=()=>{document.querySelectorAll('.shop-categories button').forEach(x=>x.classList.remove('active'));b.classList.add('active');renderShop(b.dataset.filter)});$('sound-btn').onclick=()=>{muted=!muted;$('sound-btn').style.color=muted?'#71818d':'#c2d5e0'};
    renderShop('all');updateHud();$('crosshair-hint').classList.add('show');connect();requestAnimationFrame(frame);
  }
  function mat(color,roughness=.65,metalness=.1,emissive=0){return new THREE.MeshStandardMaterial({color,roughness,metalness,emissive,emissiveIntensity:.35})}
  function box(parent,x,y,z,sx,sy,sz,material){const m=new THREE.Mesh(new THREE.BoxGeometry(sx,sy,sz),material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
  function buildArena(){
    const floor= new THREE.Mesh(new THREE.CylinderGeometry(21,21,.55,64),mat(0x172734,.82,.22));floor.position.y=-.35;floor.receiveShadow=true;arenaGroup.add(floor);
    const disk=new THREE.Mesh(new THREE.CircleGeometry(19.2,64),mat(0x101e29,.75,.3));disk.rotation.x=-Math.PI/2;disk.position.y=-.065;arenaGroup.add(disk);
    const grid=new THREE.GridHelper(38,28,0x3e8794,0x29414d);grid.position.y=-.045;grid.material.transparent=true;grid.material.opacity=.25;arenaGroup.add(grid);
    const rim=new THREE.Mesh(new THREE.TorusGeometry(19.5,.17,8,90),new THREE.MeshStandardMaterial({color:0x42c8d6,emissive:0x167681,emissiveIntensity:1.5,metalness:.6}));rim.rotation.x=Math.PI/2;rim.position.y=.02;arenaGroup.add(rim);
    const wallmat=mat(0x263e4b,.45,.62);for(let i=0;i<24;i++){let a=i/24*Math.PI*2,r=20.1;const pillar=box(arenaGroup,Math.cos(a)*r,1.35,Math.sin(a)*r,.55,2.8,.7,wallmat);pillar.rotation.y=-a;}
    for(let i=0;i<8;i++){let a=i/8*Math.PI*2;const p=new THREE.PointLight(i%2?0x3bd7e8:0xff6b58,1.3,9);p.position.set(Math.cos(a)*17,2,Math.sin(a)*17);scene.add(p);const orb=new THREE.Mesh(new THREE.OctahedronGeometry(.23),mat(i%2?0x57e6f4:0xff8065,.25,.3,i%2?0x20adba:0xa52d20));orb.position.copy(p.position);arenaGroup.add(orb);}
    for(let i=0;i<13;i++){const a=i*2.4,r=7+Math.random()*9;const rock=new THREE.Mesh(new THREE.DodecahedronGeometry(.5+Math.random()*.7,0),mat(i%3?0x253d4a:0x354858,.75,.3));rock.position.set(Math.cos(a)*r,.23,Math.sin(a)*r);rock.scale.y=.7;rock.castShadow=true;arenaGroup.add(rock);}
    for(let i=0;i<5;i++){let a=i*Math.PI*2/5;const rune=new THREE.Mesh(new THREE.TorusGeometry(1.6,.035,6,40),mat(0x286674,.35,.3,0x174955));rune.position.set(Math.cos(a)*12,.01,Math.sin(a)*12);rune.rotation.x=Math.PI/2;arenaGroup.add(rune);}
  }
  function makeRanger(x,z,isPlayer=false,color=0x65dce8){const g=new THREE.Group();g.position.set(x,0,z);g.userData={isPlayer};const armor=mat(color,.36,.66,0x10363d),dark=mat(0x182531,.55,.55),glow=mat(isPlayer?0x65f1ff:0x67d9ad,.2,.3,isPlayer?0x25aabd:0x16744c);
    const body=new THREE.Mesh(new THREE.CapsuleGeometry(.42,.75,5,8),armor);body.position.y=1.15;body.castShadow=true;g.add(body);
    const head=new THREE.Mesh(new THREE.SphereGeometry(.31,12,10),dark);head.position.y=1.83;head.castShadow=true;g.add(head);
    const visor=new THREE.Mesh(new THREE.BoxGeometry(.4,.1,.08),glow);visor.position.set(0,1.86,-.27);g.add(visor);
    const pack=box(g,0,1.2,.43,.48,.62,.23,dark);const gun=box(g,.48,1.25,-.28,.13,.16,.72,mat(0x90aeb7,.3,.8));gun.rotation.x=-.04;g.userData.gun=gun;
    const ring=new THREE.Mesh(new THREE.TorusGeometry(.57,.025,5,24),glow);ring.rotation.x=Math.PI/2;ring.position.y=.08;g.add(ring);return g;}
  function makeBoss(){const g=new THREE.Group();g.position.set(0,0,-8);g.userData={bob:0};const core= new THREE.Mesh(new THREE.IcosahedronGeometry(1.35,1),mat(0x3c465d,.23,.55,0x8a244b));core.position.y=2.1;core.castShadow=true;g.add(core);const chest=new THREE.Mesh(new THREE.OctahedronGeometry(1.7,1),new THREE.MeshStandardMaterial({color:0x292f43,roughness:.3,metalness:.7,emissive:0x481332,emissiveIntensity:.9,wireframe:false}));chest.position.y=2.1;chest.scale.set(1,1.25,.78);chest.castShadow=true;g.add(chest);
    const eyeMat=new THREE.MeshStandardMaterial({color:0xff6b79,emissive:0xff273b,emissiveIntensity:2});for(let i=-1;i<=1;i+=2){const eye=new THREE.Mesh(new THREE.SphereGeometry(.14,10,8),eyeMat);eye.position.set(i*.42,2.38,-.72);g.add(eye)}
    for(let i=-1;i<=1;i+=2){const arm=new THREE.Mesh(new THREE.CapsuleGeometry(.35,1.2,4,8),mat(0x373c51,.35,.72,0x411027));arm.position.set(i*1.6,1.6,-.05);arm.rotation.z=i*.22;arm.castShadow=true;g.add(arm);const claw=new THREE.Mesh(new THREE.ConeGeometry(.38,.8,6),mat(0x87909b,.23,.8));claw.position.set(i*1.7,.58,-.2);claw.rotation.x=Math.PI;g.add(claw)}
    for(let i=0;i<5;i++){const spike=new THREE.Mesh(new THREE.ConeGeometry(.32,1,6),mat(0x6a344b,.35,.6,0x641d3d));spike.position.set((i-2)*.48,3.5+Math.sin(i)*.15,.06);spike.rotation.z=(i-2)*-.15;g.add(spike)}
    const aura=new THREE.Mesh(new THREE.TorusGeometry(2.6,.055,7,48),mat(0x9f304e,.25,.4,0x63132e));aura.rotation.x=Math.PI/2;aura.position.y=.08;g.add(aura);
    const light=new THREE.PointLight(0xff365c,1.5,8);light.position.y=2.4;g.add(light);return g;}
  function spawnAllies(){for(let i=0;i<2;i++){const a=makeRanger((i?1:-1)*3,2+i*2,false,0x53c99b);a.userData.bot=true;a.userData.phase=Math.random()*6;scene.add(a);allies.push(a)}}
  function spawnEnemy(){if(enemies.length>9)return;let a=Math.random()*Math.PI*2,r=12+Math.random()*5;const g=new THREE.Group();g.position.set(Math.cos(a)*r,0,Math.sin(a)*r);g.userData={hp:40,speed:1.5+Math.random()};const body=new THREE.Mesh(new DodecahedronGeometry(.5,0),mat(0x9a4456,.4,.32,0x34111f));body.position.y=.7;body.castShadow=true;g.add(body);const eye=new THREE.Mesh(new THREE.SphereGeometry(.12,8,8),mat(0xff7c65,.25,.2,0xff3d35));eye.position.set(0,.8,-.4);g.add(eye);scene.add(g);enemies.push(g)}
  function spawnCoin(){const a=Math.random()*Math.PI*2,r=3+Math.random()*14;const g=new THREE.Group();g.position.set(Math.cos(a)*r,.5,Math.sin(a)*r);g.userData.coin=true;const c=new THREE.Mesh(new THREE.OctahedronGeometry(.28),new THREE.MeshStandardMaterial({color:0x53e8ff,metalness:.65,roughness:.2,emissive:0x148bba,emissiveIntensity:1.5}));g.add(c);const ring=new THREE.Mesh(new THREE.TorusGeometry(.4,.025,5,20),mat(0x65eaff,.2,.5,0x227ca0));ring.rotation.x=Math.PI/2;g.add(ring);scene.add(g);pickups.push(g)}
  function fire(){if(!running||!alive||Date.now()-shotAt< (weapon.id==='storm-smg'?140:250))return;shotAt=Date.now();const target=aimPoint();const origin=player.position.clone();origin.y=1.25;let dir=new THREE.Vector3(target.x-player.position.x,0,target.z-player.position.z).normalize();player.rotation.y=Math.atan2(dir.x,dir.z);const b=new THREE.Mesh(new THREE.SphereGeometry(.085,8,8),new THREE.MeshBasicMaterial({color:weapon.type==='mystic'?0xc99cff:0x8ceeff}));b.position.copy(origin).add(dir.clone().multiplyScalar(.8));b.userData={dir,life:1.2,damage:weapon.damage};scene.add(b);bullets.push(b);if(!muted)beep(weapon.type==='mystic'?520:240,.035);}
  function aimPoint(){const rect=renderer.domElement.getBoundingClientRect();const ndc=new THREE.Vector2((mouse.x/rect.width)*2-1,-(mouse.y/rect.height)*2+1);raycaster.setFromCamera(ndc,camera);const p=new THREE.Vector3();raycaster.ray.intersectPlane(groundPlane,p);return p;}
  function keyDown(e){if(e.repeat)return;held[e.code]=true;if(e.code==='KeyB'){openShop();return}if(e.code==='Escape'){closeShop();return}if(e.code==='KeyQ')arcBlast();if(e.code==='KeyR')phaseDash();if(e.code==='KeyE')interactRevive();if(e.code==='Space'){e.preventDefault();phaseDash()}}
  function arcBlast(){if(!running||!alive||Date.now()-skillAt<4500)return;skillAt=Date.now();const ring=new THREE.Mesh(new THREE.TorusGeometry(.6,.11,8,42),mat(0x74edff,.2,.25,0x24d4e7));ring.rotation.x=Math.PI/2;ring.position.set(player.position.x,.15,player.position.z);scene.add(ring);effects.push({mesh:ring,t:0,kind:'blast'});enemies.forEach(e=>{if(e.position.distanceTo(player.position)<7)e.userData.hp-=70});if(boss.position.distanceTo(player.position)<8)damageBoss(70);toast('ARC BLAST // IMPACTO');}
  function phaseDash(){if(!running||!alive||Date.now()-dashAt<2200)return;dashAt=Date.now();let move=new THREE.Vector3((held.KeyD?1:0)-(held.KeyA?1:0),0,(held.KeyS?1:0)-(held.KeyW?1:0));if(move.lengthSq()===0)move.set(0,0,-1);move.normalize();player.position.add(move.multiplyScalar(3.2));player.position.x=clamp(player.position.x,-17.5,17.5);player.position.z=clamp(player.position.z,-17.5,17.5);player.userData.invuln=Date.now()+650;toast('PHASE DASH');}
  function interactRevive(){if(down){return}let target=null,best=3.1;for(const [id,p] of remotes){if(p.state==='down'){const d=Math.hypot(player.position.x-p.mesh.position.x,player.position.z-p.mesh.position.z);if(d<best){best=d;target=p}}}if(target){if(reviveTarget!==target.id){reviveTarget=target.id;reviveSlaps=0;send({type:'revive-start',target:target.id});toast('AGARRE INICIADO // E PARA APLICAR 3 TAPAS');return}reviveSlaps++;send({type:'revive-slap',target:target.id});toast(`TAPA ${Math.min(reviveSlaps,3)} / 3`);if(reviveSlaps>=3){reviveTarget=null;reviveSlaps=0;}return}const ally=allies.find(a=>a.userData.down&&a.position.distanceTo(player.position)<3.1);if(ally){ally.userData.down=false;ally.userData.hp=60;ally.visible=true;toast('ALIADO RESSUSCITADO // EQUIPAMENTO PRESERVADO');return}toast('NENHUM ESPECTRO AO ALCANCE');}
  function damageBoss(amount){if(bossHp<=0)return;bossHp=Math.max(0,bossHp-amount);$('boss-bar').style.width=bossHp+'%';$('boss-hp-label').textContent=Math.ceil(bossHp)+'%';boss.children[1].material.emissiveIntensity=1.7;setTimeout(()=>{if(boss?.children[1])boss.children[1].material.emissiveIntensity=.9},90);if(bossHp<=0){$('boss-state').textContent='NÚCLEO EXPOSTO';bossDeath()}}
  function bossDeath(){const reward=60+wave*20;coins+=reward;updateHud();toast(`GUARDIÃO ELIMINADO // +${reward} MOEDAS AZUIS`);for(let i=0;i<9;i++)spawnCoin();phase++;$('phase').textContent=String(phase).padStart(2,'0');setTimeout(()=>{bossHp=100;$('boss-bar').style.width='100%';$('boss-hp-label').textContent='100%';$('boss-state').textContent='NOVA ENTIDADE DETECTADA';boss.position.set((Math.random()-.5)*8,0,-8);wave++;$('wave-number').textContent=String(wave).padStart(2,'0');for(let i=0;i<3;i++)spawnEnemy()},4500)}
  function takeDamage(amount){if(!alive||down||Date.now()<(player.userData.invuln||0))return;hp=Math.max(0,hp-amount);$('hit-flash').classList.remove('on');void $('hit-flash').offsetWidth;$('hit-flash').classList.add('on');if(ws)send({type:'damage',amount});if(hp<=0){lives--;if(lives<=0){lives=0;down=true;alive=false;player.visible=false;$('down-overlay').classList.add('open');$('revive-status').textContent='AGUARDANDO UM ALIADO...';}else{hp=100;toast(`VIDA PERDIDA // ${lives} RESTANTE(S)`);player.userData.invuln=Date.now()+1800} }updateHud()}
  function reviveSelf(){down=false;alive=true;lives=1;hp=60;player.visible=true;player.userData.invuln=Date.now()+2200;$('down-overlay').classList.remove('open');toast('RESSUSCITADO // 1 VIDA · ARSENAL PRESERVADO');updateHud()}
  function updateHud(){ $('coins').textContent=coins;$('shop-coins').textContent=coins;$('hp-label').textContent=Math.ceil(hp);$('health-bar').style.width=hp+'%';$('lives-label').textContent=Array.from({length:3},(_,i)=>i<lives?'♥':'♡').join(' ');$('weapon-name').innerHTML=weapon.name.toUpperCase()+' <em>T'+weapon.tier+'</em>';renderSquad(); }
