const { spawn } = require('node:child_process');
const WebSocket = require('ws');
const server = spawn(process.execPath, ['server.js'], { stdio: 'ignore' });
const wait = ms => new Promise(resolve => setTimeout(resolve, ms));
(async () => {
  try {
    await wait(350);
    const connect = () => new Promise((resolve, reject) => {
      const ws = new WebSocket('ws://127.0.0.1:3000/ws');
      let id, player, world;
      ws.on('message', data => {
        const m = JSON.parse(data);
        if (m.type === 'welcome') { id = m.id; player = m.player; world = m.world; resolve({ ws, id, player, getWorld: () => world, on: fn => ws.on('message', d => { const x=JSON.parse(d); if(x.type==='snapshot'){player=x.players.find(p=>p.id===id);world=x.world;fn?.(x)} }) }); }
        if (m.type === 'snapshot') { player = m.players.find(p => p.id === id); world = m.world; }
      });
      ws.on('error', reject);
    });
    const a = await connect(), b = await connect();
    const waitFor = async (test, timeout=3000) => { const start=Date.now(); while(Date.now()-start<timeout){if(test())return; await wait(30)} throw Error('timed out waiting for state'); };
    a.ws.send(JSON.stringify({type:'buy', item:'storm-smg'}));
    await waitFor(()=>a.player.weapon==='storm-smg' && a.player.coins===40);
    a.ws.send(JSON.stringify({type:'boss-hit'}));
    await waitFor(()=>a.getWorld().bossHp<100);
    a.ws.send(JSON.stringify({type:'damage', amount:35}));
    await waitFor(()=>a.player.hp===65);
    console.log(JSON.stringify({purchase:true,bossHp:a.getWorld().bossHp,damageHp:a.player.hp,connectedPlayers:2}));
    a.ws.close(); b.ws.close();
  } catch (error) { console.error(error.message); process.exitCode = 1; }
  finally { server.kill(); }
})();
