const WebSocket = require('ws');
const url = 'ws://127.0.0.1:3197/ws';
const sleep = ms => new Promise(r => setTimeout(r, ms));
function client() {
  const ws = new WebSocket(url), state = { player: null, players: [], world: null };
  ws.on('message', raw => {
    const m = JSON.parse(raw);
    if (m.type === 'welcome') { state.player = m.player; state.world = m.world; }
    if (m.type === 'snapshot') { state.players = m.players; state.world = m.world; state.player = m.players.find(p => p.id === state.player?.id) || state.player; }
  });
  return new Promise((resolve, reject) => { ws.once('open', () => { const t=setInterval(()=>{if(state.player){clearInterval(t);resolve({ws,state})}},10); setTimeout(()=>{clearInterval(t);reject(Error('welcome timeout'))},3000); ws.once('error',reject); }); ws.once('error',reject); });
}
async function until(fn, label, timeout=4000) { const end=Date.now()+timeout; while(Date.now()<end){if(fn())return; await sleep(20)} throw Error(`timeout: ${label}`); }
(async()=>{
 let a,b;
 try {
  a=await client(); b=await client();
  a.ws.send(JSON.stringify({type:'buy',item:'storm-smg'}));
  await until(()=>a.state.player.weapon==='storm-smg' && a.state.player.coins===40,'purchase');
  a.ws.send(JSON.stringify({type:'boss-hit'}));
  await until(()=>a.state.world.bossHp<100,'boss hit');
  for(let i=0;i<6;i++){
   b.ws.send(JSON.stringify({type:'damage',amount:60}));
   await sleep(35);
  }
  await until(()=>b.state.player.state==='down','three lives to specter');
  let ap=a.state.player, bp=b.state.player;
  while(Math.hypot(ap.x-bp.x,ap.z-bp.z)>2.6){
   const dx=bp.x-ap.x,dz=bp.z-ap.z,d=Math.hypot(dx,dz),step=Math.min(3.2,d-2.2);
   const x=ap.x+dx/d*step,z=ap.z+dz/d*step;
   a.ws.send(JSON.stringify({type:'dash',x,z})); await sleep(120);
   ap=a.state.player;bp=b.state.player;
  }
  a.ws.send(JSON.stringify({type:'revive-start',target:bp.id}));
  await until(()=>b.state.player.revive?.by===ap.id,'revive grab');
  for(let i=0;i<3;i++){await sleep(370);a.ws.send(JSON.stringify({type:'revive-slap',target:bp.id}));}
  await until(()=>b.state.player.state==='alive'&&b.state.player.lives===1,'revive complete');
  console.log(JSON.stringify({purchase:true,bossHp:a.state.world.bossHp,downedLives:b.state.player.lives,revived:b.state.player.state,revivedLives:b.state.player.lives,inventoryPreserved:b.state.player.inventory.includes('field-rifle')}));
 } catch(e){console.error(e.message);process.exitCode=1}
 finally{a?.ws.close();b?.ws.close()}
})();
